const $=id=>document.getElementById(id);let token='',page=1,jpage=1,total=0,jtotal=0;
const notice=s=>$('notice').textContent=s;
async function api(path,method='GET',data){const r=await fetch('/api/admin/'+path,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function safe(fn){try{await fn()}catch(e){notice(e.message)}}
function row(parent,values){const r=document.createElement('tr');for(const v of values){const c=document.createElement('td');c.textContent=v;r.append(c)}parent.append(r);return r}
function options(id,items,label,key='id'){const s=$(id);s.replaceChildren(new Option('Sélectionner',''));for(const x of items)s.append(new Option(label(x),x[key]))}
async function lookup(){const t=token,d=await api('missions?page='+encodeURIComponent($('mission-page').value));if(!token||t!==token)return;const label=m=>m.company+' / '+m.title+' ('+m.currency+')';options('milestone-mission',d.items.filter(m=>m.mode==='FORFAIT'),label,'mission_id');options('invoice-mission',d.items,label,'mission_id');options('schedule-mission',d.items,label,'mission_id');options('expense-mission',d.items,label,'mission_id');$('expense-mission').options[0].textContent='Sans mission'}
async function load(){const t=token,[d,j]=await Promise.all([api('billing?page='+page),api('billing/milestones?page='+jpage)]);if(!token||t!==token)return;total=d.total;jtotal=j.total;for(const id of ['rows','totals','milestone-rows'])$(id).replaceChildren();for(const [c,v] of Object.entries(d.totals))row($('totals'),[c,v.invoiced,v.paid,v.balance,v.overdue]);for(const x of d.items)row($('rows'),[x.reference+' / '+x.title,x.amount+' '+x.currency,x.paid,x.balance,x.due_date,x.overdue?'En retard':Number(x.balance)===0?'Soldée':'À encaisser']);options('payment-invoice',d.items.filter(x=>Number(x.balance)>0),x=>x.reference+' / '+x.balance+' '+x.currency);for(const x of j.items){const r=row($('milestone-rows'),[x.mission_title,x.title,x.amount+' '+x.currency,x.status,'']);if(x.status==='PREVU'){const b=document.createElement('button');b.textContent='Valider';b.onclick=()=>safe(async()=>{if(!confirm('Valider définitivement ce jalon ?'))return;await api('billing/milestones/'+x.id,'PATCH',{status:'VALIDE'});await load()});r.lastChild.append(b)}}$('page').textContent='Page '+page+' / '+total+' créance(s)';$('jpage').textContent='Page '+jpage+' / '+jtotal+' jalon(s)';$('prev').disabled=page===1;$('next').disabled=page*25>=total;$('jprev').disabled=jpage===1;$('jnext').disabled=jpage*25>=jtotal;await Promise.all([loadExpenses(),loadContracts(),loadSchedule(),loadCollections()])}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';try{await load();await lookup();$('login').hidden=true;$('workspace').hidden=false}catch(e){token='';notice(e.message)}};
$('logout').onclick=()=>{token='';$('workspace').hidden=true;$('login').hidden=false;for(const id of ['rows','totals','milestone-rows','payment-invoice','invoice-mission','milestone-mission','expense-mission','expense-rows','cash-rows','contract-rows','schedule-rows','schedule-mission','aging-rows','collection-rows'])$(id).replaceChildren();for(const id of ['milestone','invoice','payment','expense','schedule'])$(id).reset();notice('Déconnecté.')};$('lookup').onclick=()=>safe(lookup);
for(const [id,kind] of [['milestone','milestones'],['invoice','invoices'],['payment','payments']])$(id).onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{await api('billing/'+kind,'POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await load();notice('Enregistrement effectué.')}finally{b.disabled=false}})};
$('prev').onclick=()=>{if(page>1){page--;safe(load)}};$('next').onclick=()=>{if(page*25<total){page++;safe(load)}};$('jprev').onclick=()=>{if(jpage>1){jpage--;safe(load)}};$('jnext').onclick=()=>{if(jpage*25<jtotal){jpage++;safe(load)}};
let expensePage=1,expenseTotal=0;
async function loadExpenses(){const t=token,d=await api('billing/expenses?page='+expensePage);if(!token||t!==token)return;expenseTotal=d.total;$('cash-rows').replaceChildren();$('expense-rows').replaceChildren();for(const x of d.cash)row($('cash-rows'),[x.currency,x.received,x.outflows,x.net_flow]);for(const x of d.items)row($('expense-rows'),[x.reference,x.paid_date,x.category,x.amount+' '+x.currency,x.mission_title||'Sans mission',x.description]);$('epage').textContent='Page '+expensePage+' · '+expenseTotal+' dépense(s)';$('eprev').disabled=expensePage===1;$('enext').disabled=expensePage*25>=expenseTotal;}
$('expense').onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{await api('billing/expenses','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();expensePage=1;await loadExpenses();notice('Décaissement enregistré.')}finally{b.disabled=false}})};
$('eprev').onclick=()=>{if(expensePage>1){expensePage--;safe(loadExpenses)}};$('enext').onclick=()=>{if(expensePage*25<expenseTotal){expensePage++;safe(loadExpenses)}};

let contractPage=1,contractTotal=0;
async function loadContracts(){const t=token,d=await api('billing/contracts?page='+contractPage);if(!token||t!==token)return;contractTotal=d.total;$('contract-rows').replaceChildren();for(const x of d.items)row($('contract-rows'),[x.company+' / '+x.contract_ref+' / '+x.title,x.currency,x.planned,x.earned,x.invoiced,x.paid,x.balance,x.overdue,x.remaining_billable,x.actual_cost,x.earned_margin]);$('cpage').textContent='Page '+contractPage+' · '+contractTotal+' contrat(s)';$('cprev').disabled=contractPage===1;$('cnext').disabled=contractPage*25>=contractTotal}
$('cprev').onclick=()=>{if(contractPage>1){contractPage--;safe(loadContracts)}};$('cnext').onclick=()=>{if(contractPage*25<contractTotal){contractPage++;safe(loadContracts)}};

let schedulePage=1,scheduleTotal=0;
async function loadSchedule(){const t=token,d=await api('billing/schedule?page='+schedulePage);if(!token||t!==token)return;scheduleTotal=d.total;$('schedule-rows').replaceChildren();for(const x of d.items){const r=row($('schedule-rows'),[x.company+' / '+x.contract_ref,x.label+' / '+x.kind,x.amount+' '+x.currency,x.due_date,x.overdue?'Prévision dépassée':x.state+(x.invoice_reference?' / '+x.invoice_reference:''),'']);if(x.state==='PREVU'){const input=document.createElement('input');input.placeholder='Référence créance';input.setAttribute('aria-label','Référence créance');const link=document.createElement('button'),cancel=document.createElement('button');link.textContent='Rapprocher';cancel.textContent='Annuler';link.onclick=()=>safe(async()=>{await api('billing/schedule/'+x.id,'PATCH',{invoice_reference:input.value});await loadSchedule()});cancel.onclick=()=>safe(async()=>{if(confirm('Annuler cette prévision ?')){await api('billing/schedule/'+x.id,'PATCH',{state:'ANNULE'});await loadSchedule()}});r.lastChild.append(input,link,cancel)}}$('spage').textContent='Page '+schedulePage+' · '+scheduleTotal+' échéance(s)';$('sprev').disabled=schedulePage===1;$('snext').disabled=schedulePage*25>=scheduleTotal}
$('schedule').onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{await api('billing/schedule','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();schedulePage=1;await loadSchedule();notice('Échéance planifiée.')}finally{b.disabled=false}})};
$('sprev').onclick=()=>{if(schedulePage>1){schedulePage--;safe(loadSchedule)}};$('snext').onclick=()=>{if(schedulePage*25<scheduleTotal){schedulePage++;safe(loadSchedule)}};

let collectionPage=1,collectionTotal=0;
async function loadCollections(){
 const t=token,d=await api('billing/receivables?page='+collectionPage);if(!token||t!==token)return;
 collectionTotal=d.total;for(const id of ['aging-rows','collection-rows'])$(id).replaceChildren();
 for(const [c,v] of Object.entries(d.aging))row($('aging-rows'),[c,v.current,v.d1_30,v.d31_60,v.d61_90,v.d90_plus]);
 for(const x of d.items){
  const r=row($('collection-rows'),[x.company+' / '+x.reference,x.balance+' '+x.currency,x.due_date,x.days_overdue,x.reminder_count+' · '+x.reminders.map(y=>y.created_at+' '+y.channel+' : '+y.note).join(' | '),'']);
  if(x.days_overdue>0){const channel=document.createElement('select');channel.setAttribute('aria-label','Canal de relance');for(const c of ['EMAIL','TELEPHONE','WHATSAPP','AUTRE'])channel.append(new Option(c,c));const note=document.createElement('input');note.maxLength=180;note.placeholder='Compte rendu';note.setAttribute('aria-label','Compte rendu de relance');const b=document.createElement('button');b.textContent='Consigner la relance';b.onclick=()=>safe(async()=>{if(!note.value.trim())return notice('Compte rendu obligatoire.');b.disabled=true;try{await api('billing/reminders','POST',{invoice_id:x.id,channel:channel.value,note:note.value});await loadCollections();notice('Relance consignée, aucun message envoyé.')}finally{b.disabled=false}});r.lastChild.append(channel,note,b)}
 }
 $('rpage').textContent='Page '+collectionPage+' · '+collectionTotal+' créance(s) ouverte(s)';$('rprev').disabled=collectionPage===1;$('rnext').disabled=collectionPage*25>=collectionTotal;
}
$('rprev').onclick=()=>{if(collectionPage>1){collectionPage--;safe(loadCollections)}};$('rnext').onclick=()=>{if(collectionPage*25<collectionTotal){collectionPage++;safe(loadCollections)}};
